args.sparql:
SELECT ?winner WHERE {
  ?winner p:P1213 ?awardStatement .
  ?awardStatement ps:P1213 wd:Q1035785 .
  ?awardStatement pq:P585 [
    wikibase:timeValue "2017-01-01T00:00:00Z"^^xsd:dateTime
  ] .
}

SELECT ?winner ?winnerLabel WHERE {
  wd:Q2156552 p:P937 ?statement.
  ?statement ps:P937 ?winner.
  ?statement pq:P585 ?date.
  ?date wikibase:timeValue ?time.
  FILTER(STRSTARTS(STR(?time), "2017"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
